/* Auto-generated — Attendance Sheet Template (base64) */
const TEMPLATE_B64 = '';

function downloadTemplate() {
  const byteChars = atob(TEMPLATE_B64);
  const byteArr   = new Uint8Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) byteArr[i] = byteChars.charCodeAt(i);
  const blob = new Blob([byteArr], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href     = url;
  a.download = 'Attendance_Sheet_Template.xlsx';
  a.click();
  URL.revokeObjectURL(url);
}
